import java.util.List;

public class Solution {
  /**
   * 堆里只放 (值, run 下标, run 内游标)：弹出后才推进对应 run，天然惰性。
   * 比较器用 Comparator.comparingInt（绝不做减法），所以 MIN_VALUE 参与也不会错序。
   * 用 PriorityQueue 而不是 TreeSet：重复值在 TreeSet 里因 compareTo==0 会被静默丢弃。
   */
  public static int[] mergeKSmallest(List<List<Integer>> runs, int k) {
    if (runs == null || runs.isEmpty() || k <= 0) return new int[0];
    int total = 0;
    java.util.PriorityQueue<int[]> heap =
        new java.util.PriorityQueue<int[]>(java.util.Comparator.comparingInt(a -> a[0]));
    for (int r = 0; r < runs.size(); r++) {
      List<Integer> run = runs.get(r);
      total += run.size();
      if (!run.isEmpty()) heap.add(new int[] { run.get(0), r, 0 });
    }
    int want = Math.min(k, total);
    int[] out = new int[want];
    for (int pos = 0; pos < want; pos++) {
      int[] top = heap.poll();
      out[pos] = top[0];
      List<Integer> run = runs.get(top[1]);
      int next = top[2] + 1;
      if (next < run.size()) heap.add(new int[] { run.get(next), top[1], next });
    }
    return out;
  }
}

