import java.util.List;

public class Solution {
  // 朴素：只看每条 run 的队首（相当于"每条 run 最多贡献一条"），弹出后不推进游标。
  // 于是 run 里第 2 个及之后的元素永远进不了结果，k 大于 run 条数时就少发了。
  public static int[] mergeKSmallest(List<List<Integer>> runs, int k) {
    java.util.List<Integer> heads = new java.util.ArrayList<>();
    for (List<Integer> run : runs) {
      if (!run.isEmpty()) heads.add(run.get(0));
    }
    java.util.Collections.sort(heads);
    int want = Math.min(k, heads.size());
    int[] out = new int[want];
    for (int pos = 0; pos < want; pos++) out[pos] = heads.get(pos);
    return out;
  }
}
